module ietf-routing {
  namespace "urn:ietf:params:xml:ns:yang:ietf-routing";
  prefix rt;

  organization
    "IETF NETMOD (Network Modeling) Working Group";
  contact
    "WG Web:   <https://datatracker.ietf.org/wg/netmod/>
     WG List:  <mailto:rtgwg@ietf.org>

     Editor:   Ladislav Lhotka
               <mailto:lhotka@nic.cz>
               Acee Lindem
               <mailto:acee@cisco.com>
               Yingzhen Qu
               <mailto:yingzhen.qu@huawei.com>";
  description
    "This YANG module defines essential components for the management
     of a routing subsystem.  The model fully conforms to the Network
     Management Datastore Architecture (NMDA).

     Copyright (c) 2018 IETF Trust and the persons
     identified as authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).
     This version of this YANG module is part of RFC 8349; see
     the RFC itself for full legal notices.";

  revision 2018-03-13;

  identity address-family {
    derived ipv4;
    derived ipv6;
    description
      "Base identity from which identities describing address
       families are derived.";
  }

  identity ipv4 {
    description
      "This identity represents an IPv4 address family.";
  }

  identity ipv6 {
    description
      "This identity represents an IPv6 address family.";
  }

  identity control-plane-protocol {
    derived routing-protocol;
    derived bfd-types:bfdv1;
    description
      "Base identity from which control-plane protocol identities are
       derived.";
  }

  identity routing-protocol {
    derived direct;
    derived static;
    derived ospf:ospf;
    description
      "Identity from which Layer 3 routing protocol identities are
       derived.";
  }

  identity direct {
    description
      "Routing pseudo-protocol that provides routes to directly
       connected networks.";
  }

  identity static {
    description
      "'Static' routing pseudo-protocol.";
  }

  container routing {
    config true;
    status current;
    description
      "Configuration parameters for the routing subsystem.";
    leaf router-id {
      type string {
        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
      }
      config true;
      status current;
      description
        "A 32-bit number in the form of a dotted quad that is used by
         some routing protocols identifying a router.";
      reference
        "RFC 2328: OSPF Version 2";
    }
    container interfaces {
      config false;
      status current;
      description
        "Network-layer interfaces used for routing.";
      leaf-list interface {
        type leafref {
          path "/if:interfaces/if:interface/if:name";
          require-instance true;
          type string;
        }
        config false;
        min-elements 0;
        max-elements 4294967295;
        ordered-by user;
        status current;
        description
          "Each entry is a reference to the name of a configured
           network-layer interface.";
      }
    }
    container control-plane-protocols {
      config true;
      status current;
      description
        "Support for control-plane protocol instances.";
      list control-plane-protocol {
        key "typename";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "Each entry contains a control-plane protocol instance.";
        leaf type {
          type identityref {
            base control-plane-protocol;
          }
          config true;
          status current;
          description
            "Type of the control-plane protocol -- an identity
             derived from the 'control-plane-protocol'
             base identity.";
        }
        leaf name {
          type string;
          config true;
          status current;
          description
            "An arbitrary name of the control-plane protocol
             instance.";
        }
        leaf description {
          type string;
          config true;
          status current;
          description
            "Textual description of the control-plane protocol
             instance.";
        }
        container static-routes {
          when "derived-from-or-self(../type, 'rt:static')" {
            description
              "This container is only valid for the 'static' routing
               protocol.";
          }
          config true;
          status current;
          description
            "Support for the 'static' pseudo-protocol.

             Address-family-specific modules augment this node with
             their lists of routes.";
        }
        container ospf {
          when "derived-from(rt:type, 'ospf')" {
            description
              "This augmentation is only valid for a routing protocol
               instance of OSPF (type 'ospfv2' or 'ospfv3').";
          }
          config true;
          status current;
          description
            "OSPF protocol instance.";
          leaf address-family {
            when "derived-from-or-self(../../rt:type, 'ospfv3')" {
              description
                "Only applicable to OSPFv3.";
            }
            type enumeration {
              enum "ipv4" {
                value 1;
                status current;
                description
                  "IPv4 Address Family.";
              }
              enum "ipv6" {
                value 2;
                status current;
                description
                  "IPv6 Address Family.";
              }
              enum "nsap" {
                value 3;
                status current;
                description
                  "OSI Network Service Access Point (NSAP) Address Family.";
              }
              enum "hdlc" {
                value 4;
                status current;
                description
                  "High-Level Data Link Control (HDLC) Address Family.";
              }
              enum "bbn1822" {
                value 5;
                status current;
                description
                  "Bolt, Beranek, and Newman Report 1822 (BBN 1822)
                   Address Family.";
              }
              enum "ieee802" {
                value 6;
                status current;
                description
                  "IEEE 802 Committee Address Family
                   (aka Media Access Control (MAC) address).";
              }
              enum "e163" {
                value 7;
                status current;
                description
                  "ITU-T E.163 Address Family.";
              }
              enum "e164" {
                value 8;
                status current;
                description
                  "ITU-T E.164 (Switched Multimegabit Data Service (SMDS),
                   Frame Relay, ATM) Address Family.";
              }
              enum "f69" {
                value 9;
                status current;
                description
                  "ITU-T F.69 (Telex) Address Family.";
              }
              enum "x121" {
                value 10;
                status current;
                description
                  "ITU-T X.121 (X.25, Frame Relay) Address Family.";
              }
              enum "ipx" {
                value 11;
                status current;
                description
                  "Novell Internetwork Packet Exchange (IPX)
                   Address Family.";
              }
              enum "appletalk" {
                value 12;
                status current;
                description
                  "Apple AppleTalk Address Family.";
              }
              enum "decnet-iv" {
                value 13;
                status current;
                description
                  "Digital Equipment DECnet Phase IV Address Family.";
              }
              enum "vines" {
                value 14;
                status current;
                description
                  "Banyan Vines Address Family.";
              }
              enum "e164-nsap" {
                value 15;
                status current;
                description
                  "ITU-T E.164 with NSAP sub-address Address Family.";
              }
              enum "dns" {
                value 16;
                status current;
                description
                  "Domain Name System (DNS) Address Family.";
              }
              enum "distinguished-name" {
                value 17;
                status current;
                description
                  "Distinguished Name Address Family.";
              }
              enum "as-num" {
                value 18;
                status current;
                description
                  "Autonomous System (AS) Number Address Family.";
              }
              enum "xtp-v4" {
                value 19;
                status current;
                description
                  "Xpress Transport Protocol (XTP) over IPv4
                   Address Family.";
              }
              enum "xtp-v6" {
                value 20;
                status current;
                description
                  "XTP over IPv6 Address Family.";
              }
              enum "xtp-native" {
                value 21;
                status current;
                description
                  "XTP native mode Address Family.";
              }
              enum "fc-port" {
                value 22;
                status current;
                description
                  "Fibre Channel (FC) World-Wide Port Name Address Family.";
              }
              enum "fc-node" {
                value 23;
                status current;
                description
                  "FC World-Wide Node Name Address Family.";
              }
              enum "gwid" {
                value 24;
                status current;
                description
                  "ATM Gateway Identifier (GWID) Number Address Family.";
              }
              enum "l2vpn" {
                value 25;
                status current;
                description
                  "Layer 2 VPN (L2VPN) Address Family.";
              }
              enum "mpls-tp-section-eid" {
                value 26;
                status current;
                description
                  "MPLS Transport Profile (MPLS-TP) Section Endpoint
                   Identifier Address Family.";
              }
              enum "mpls-tp-lsp-eid" {
                value 27;
                status current;
                description
                  "MPLS-TP Label Switched Path (LSP) Endpoint Identifier
                   Address Family.";
              }
              enum "mpls-tp-pwe-eid" {
                value 28;
                status current;
                description
                  "MPLS-TP Pseudowire Endpoint Identifier Address Family.";
              }
              enum "mt-v4" {
                value 29;
                status current;
                description
                  "Multi-Topology IPv4 Address Family.";
              }
              enum "mt-v6" {
                value 30;
                status current;
                description
                  "Multi-Topology IPv6 Address Family.";
              }
              enum "bgp-sfc" {
                value 31;
                status current;
                description
                  "BGP SFC Address Family.";
                reference
                  "RFC 9015: BGP Control Plane for the Network Service Header in Service Function Chaining.";
              }
              enum "eigrp-common-sf" {
                value 16384;
                status current;
                description
                  "Enhanced Interior Gateway Routing Protocol (EIGRP)
                   Common Service Family Address Family.";
              }
              enum "eigrp-v4-sf" {
                value 16385;
                status current;
                description
                  "EIGRP IPv4 Service Family Address Family.";
              }
              enum "eigrp-v6-sf" {
                value 16386;
                status current;
                description
                  "EIGRP IPv6 Service Family Address Family.";
              }
              enum "lcaf" {
                value 16387;
                status current;
                description
                  "Locator/ID Separation Protocol (LISP)
                   Canonical Address Format (LCAF) Address Family.";
              }
              enum "bgp-ls" {
                value 16388;
                status current;
                description
                  "Border Gateway Protocol - Link State (BGP-LS)
                   Address Family.";
              }
              enum "mac-48" {
                value 16389;
                status current;
                description
                  "IEEE 48-bit MAC Address Family.";
              }
              enum "mac-64" {
                value 16390;
                status current;
                description
                  "IEEE 64-bit MAC Address Family.";
              }
              enum "trill-oui" {
                value 16391;
                status current;
                description
                  "Transparent Interconnection of Lots of Links (TRILL)
                   IEEE Organizationally Unique Identifier (OUI)
                   Address Family.";
              }
              enum "trill-mac-24" {
                value 16392;
                status current;
                description
                  "TRILL final 3 octets of 48-bit MAC Address Family.";
              }
              enum "trill-mac-40" {
                value 16393;
                status current;
                description
                  "TRILL final 5 octets of 64-bit MAC Address Family.";
              }
              enum "ipv6-64" {
                value 16394;
                status current;
                description
                  "First 8 octets (64 bits) of IPv6 address
                   Address Family.";
              }
              enum "trill-rbridge-port-id" {
                value 16395;
                status current;
                description
                  "TRILL Routing Bridge (RBridge) Port ID Address Family.";
              }
              enum "trill-nickname" {
                value 16396;
                status current;
                description
                  "TRILL Nickname Address Family.";
              }
              enum "universally-unique-identifier" {
                value 16397;
                status current;
                description
                  "Universally Unique Identifier (UUID).";
              }
              enum "routing-policy" {
                value 16398;
                status current;
                description
                  "Routing Policy Address Family.";
              }
              enum "mpls-namespaces" {
                value 16399;
                status current;
                description
                  "MPLS Namespaces Address Family.";
              }
            }
            config true;
            status current;
            description
              "Address family of the instance.";
          }
          leaf enabled {
            type boolean;
            default "true";
            config true;
            status current;
            description
              "Enables/disables the protocol.";
          }
          leaf explicit-router-id {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
            }
            config true;
            status current;
            description
              "Defined in RFC 2328.  A 32-bit number
               that uniquely identifies the router.";
            reference
              "RFC 2328: OSPF Version 2";
          }
          container preference {
            config true;
            status current;
            description
              "Route preference configuration.  In many
               implementations, preference is referred to as
               administrative distance.";
            reference
              "RFC 8349: A YANG Data Model for Routing Management
               (NMDA Version)";
            choice scope {
              config true;
              status current;
              description
                "Options for expressing preference
                 as single or multiple values.";
              case single-value {
                config true;
                status current;
                leaf all {
                  type uint8;
                  config true;
                  status current;
                  description
                    "Preference for intra-area, inter-area, and
                     external routes.";
                }
              }
              case multi-values {
                config true;
                status current;
                choice granularity {
                  config true;
                  status current;
                  description
                    "Options for expressing preference
                     for intra-area and inter-area routes.";
                  case detail {
                    config true;
                    status current;
                    leaf intra-area {
                      type uint8;
                      config true;
                      status current;
                      description
                        "Preference for intra-area routes.";
                    }
                    leaf inter-area {
                      type uint8;
                      config true;
                      status current;
                      description
                        "Preference for inter-area routes.";
                    }
                  }
                  case coarse {
                    config true;
                    status current;
                    leaf internal {
                      type uint8;
                      config true;
                      status current;
                      description
                        "Preference for both intra-area and
                         inter-area routes.";
                    }
                  }
                }
                leaf external {
                  type uint8;
                  config true;
                  status current;
                  description
                    "Preference for AS external and NSSA routes.";
                }
              }
            }
          }
          container nsr {
            config true;
            status current;
            description
              "Non-Stop Routing (NSR) configuration state.";
            leaf enabled {
              type boolean;
              config true;
              status current;
              description
                "Enables/disables NSR.";
            }
          }
          container graceful-restart {
            config true;
            status current;
            description
              "Graceful restart configuration state.";
            reference
              "RFC 3623: Graceful OSPF Restart
               RFC 5187: OSPFv3 Graceful Restart";
            leaf enabled {
              type boolean;
              config true;
              status current;
              description
                "Enables/disables graceful restart as defined in RFC 3623
                 for OSPFv2 and RFC 5187 for OSPFv3.";
            }
            leaf helper-enabled {
              type boolean;
              config true;
              status current;
              description
                "Enables graceful restart helper support for restarting
                 routers (Section 3 of RFC 3623).";
              reference
                "RFC 3623: Graceful OSPF Restart, Section 3";
            }
            leaf restart-interval {
              type uint16 {
                range "1..1800";
              }
              units "seconds";
              default "120";
              config true;
              status current;
              description
                "Interval during which to attempt graceful restart prior
                 to failing (seconds) (Appendix B.1 of RFC 3623).";
              reference
                "RFC 3623: Graceful OSPF Restart, Appendix B.1";
            }
            leaf helper-strict-lsa-checking {
              type boolean;
              config true;
              status current;
              description
                "Terminates graceful restart when an LSA topology change
                 is detected (Appendix B.2 of RFC 3623).";
              reference
                "RFC 3623: Graceful OSPF Restart, Appendix B.2";
            }
          }
          container auto-cost {
            config true;
            status current;
            description
              "Interface auto-cost configuration state.";
            leaf enabled {
              type boolean;
              config true;
              status current;
              description
                "Enables/disables interface auto-cost.";
            }
            leaf reference-bandwidth {
              when "../enabled = 'true'" {
                description
                  "Only when auto-cost is enabled.";
              }
              type uint32 {
                range "1..4294967";
              }
              units "Mbits";
              config true;
              status current;
              description
                "Configures reference bandwidth used to automatically
                 determine interface cost (Mbits).  The cost is the
                 reference bandwidth divided by the interface speed,
                 with 1 being the minimum cost.";
            }
          }
          container spf-control {
            config true;
            status current;
            description
              "SPF calculation control.";
            leaf paths {
              type uint16 {
                range "1..65535";
              }
              config true;
              status current;
              description
                "Maximum number of Equal-Cost Multi-Path (ECMP) paths.";
            }
            container ietf-spf-delay {
              config true;
              status current;
              description
                "IETF SPF delay algorithm configuration.";
              leaf initial-delay {
                type uint32;
                units "milliseconds";
                default "50";
                config true;
                status current;
                description
                  "Delay used while in the 'QUIET' state (milliseconds).";
              }
              leaf short-delay {
                type uint32;
                units "milliseconds";
                default "200";
                config true;
                status current;
                description
                  "Delay used while in the 'SHORT_WAIT' state (milliseconds).";
              }
              leaf long-delay {
                type uint32;
                units "milliseconds";
                default "5000";
                config true;
                status current;
                description
                  "Delay used while in the 'LONG_WAIT' state (milliseconds).";
              }
              leaf hold-down {
                type uint32;
                units "milliseconds";
                default "10000";
                config true;
                status current;
                description
                  "This timer value defines the period without any changes
                   for the IGP to be considered stable (milliseconds).";
              }
              leaf time-to-learn {
                type uint32;
                units "milliseconds";
                default "500";
                config true;
                status current;
                description
                  "Duration used to learn all the IGP events
                   related to a single network event (milliseconds).";
              }
              leaf current-state {
                type enumeration {
                  enum "quiet" {
                    value 0;
                    status current;
                    description
                      "'QUIET' state.";
                  }
                  enum "short-wait" {
                    value 1;
                    status current;
                    description
                      "'SHORT_WAIT' state.";
                  }
                  enum "long-wait" {
                    value 2;
                    status current;
                    description
                      "'LONG_WAIT' state.";
                  }
                }
                config false;
                status current;
                description
                  "Current SPF back-off algorithm state.";
              }
              leaf remaining-time-to-learn {
                type union {
                  type uint32 {
                    range "1..4294967295";
                  }
                  type enumeration {
                    enum "infinity" {
                      value 0;
                      status current;
                      description
                        "The timer is set to infinity.";
                    }
                    enum "not-set" {
                      value 1;
                      status current;
                      description
                        "The timer is not set.";
                    }
                  }
                }
                units "milliseconds";
                config false;
                status current;
                description
                  "Remaining time until the time-to-learn timer fires.";
              }
              leaf remaining-hold-down {
                type union {
                  type uint32 {
                    range "1..4294967295";
                  }
                  type enumeration {
                    enum "infinity" {
                      value 0;
                      status current;
                      description
                        "The timer is set to infinity.";
                    }
                    enum "not-set" {
                      value 1;
                      status current;
                      description
                        "The timer is not set.";
                    }
                  }
                }
                units "milliseconds";
                config false;
                status current;
                description
                  "Remaining time until the hold-down timer fires.";
              }
              leaf last-event-received {
                type uint32;
                config false;
                status current;
                description
                  "Time of the last SPF triggering event.";
              }
              leaf next-spf-time {
                type uint32;
                config false;
                status current;
                description
                  "Time when the next SPF has been scheduled.";
              }
              leaf last-spf-time {
                type uint32;
                config false;
                status current;
                description
                  "Time of the last SPF computation.";
              }
            }
          }
          container database-control {
            config true;
            status current;
            description
              "Database maintenance control.";
            leaf max-lsa {
              type uint32 {
                range "1..4294967294";
              }
              config true;
              status current;
              description
                "Maximum number of OSPF LSAs the router will accept.";
            }
          }
          container stub-router {
            config true;
            status current;
            description
              "Sets the maximum metric configuration.";
            choice trigger {
              config true;
              status current;
              description
                "Specific triggers that will enable stub router state.";
              case always {
                config true;
                status current;
                container always {
                  presence "true";
                  config true;
                  status current;
                  description
                    "Unconditional stub router state (advertises
                     transit links with 'MaxLinkMetric').";
                  reference
                    "RFC 6987: OSPF Stub Router Advertisement";
                }
              }
            }
          }
          container mpls {
            config true;
            status current;
            description
              "OSPF MPLS configuration state.";
            container te-rid {
              config true;
              status current;
              description
                "Stable OSPF Router IP address used for TE.";
              leaf ipv4-router-id {
                type string {
                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                }
                config true;
                status current;
                description
                  "Explicitly configures a TE IPv4 Router ID.";
              }
              leaf ipv6-router-id {
                type string {
                  pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                  pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                }
                config true;
                status current;
                description
                  "Explicitly configures a TE IPv6 Router ID.";
              }
            }
            container ldp {
              config true;
              status current;
              description
                "OSPF MPLS LDP configuration state.";
              leaf igp-sync {
                type boolean;
                config true;
                status current;
                description
                  "Enables LDP IGP synchronization.";
              }
            }
          }
          container fast-reroute {
            config true;
            status current;
            description
              "This container may be augmented with global
               parameters for IP-FRR.";
            container lfa {
              config true;
              status current;
              description
                "This container may be augmented with
                 global parameters for Loop-Free Alternates (LFAs).
                 Container creation has no effect on LFA activation.";
            }
          }
          container node-tags {
            config true;
            status current;
            description
              "Container for node administrative tags.";
            list node-tag {
              key "tag";
              config true;
              min-elements 0;
              max-elements 4294967295;
              ordered-by system;
              status current;
              description
                "List of node tags.";
              leaf tag {
                type uint32;
                config true;
                status current;
                description
                  "Node tag value.";
              }
            }
          }
          leaf router-id {
            type string {
              pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
            }
            config false;
            status current;
            description
              "Defined in RFC 2328.  A 32-bit number
               that uniquely identifies the router.";
            reference
              "RFC 2328: OSPF Version 2";
          }
          container local-rib {
            config false;
            status current;
            description
              "Local RIB.";
            list route {
              key "prefix";
              config false;
              min-elements 0;
              max-elements 4294967295;
              ordered-by user;
              status current;
              description
                "OSPF instance's Local Routes.";
              leaf prefix {
                type union {
                  type string {
