                status current;
                description
                  "Area-scope LSDB.";
                list area-scope-lsa-type {
                  key "lsa-type";
                  config false;
                  min-elements 0;
                  max-elements 4294967295;
                  ordered-by user;
                  status current;
                  description
                    "List of OSPF area-scope LSAs.";
                  leaf lsa-type {
                    type uint16;
                    config false;
                    status current;
                    description
                      "OSPF area-scope LSA type.";
                  }
                  container area-scope-lsas {
                    config false;
                    status current;
                    description
                      "All area-scope LSAs.";
                    list area-scope-lsa {
                      key "lsa-idadv-router";
                      config false;
                      min-elements 0;
                      max-elements 4294967295;
                      ordered-by user;
                      status current;
                      description
                        "List of OSPF area-scope LSAs.";
                      leaf lsa-id {
                        type union {
                          type string {
                            pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                          }
                          type uint32;
                        }
                        config false;
                        status current;
                        description
                          "Link State ID.";
                      }
                      leaf adv-router {
                        type string {
                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                        }
                        config false;
                        status current;
                        description
                          "Advertising router.";
                      }
                      leaf decode-completed {
                        type boolean;
                        config false;
                        status current;
                        description
                          "The OSPF LSA body was successfully decoded, except for
                           unknown TLVs.  Unknown LSA types and OSPFv2 unknown
                           Opaque-LSA types are not decoded.  Additionally,
                           malformed LSAs are generally not accepted and will
                           not be in the Link State Database (LSDB).";
                      }
                      leaf raw-data {
                        type string {
                          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
                        }
                        config false;
                        status current;
                        description
                          "The hexadecimal representation of the complete LSA as
                           received or originated, in network byte order.";
                      }
                      choice version {
                        config false;
                        status current;
                        description
                          "OSPFv2 or OSPFv3 LSA body.";
                        case ospfv2 {
                          config false;
                          status current;
                          container ospfv2 {
                            must "derived-from-or-self( ../../../../../../../../rt:type, 'ospfv2')" {
                              description
                                "OSPFv2 LSA.";
                            }
                            config false;
                            status current;
                            description
                              "OSPFv2 LSA.";
                            container header {
                              must "(derived-from(type, 'ospfv2-opaque-lsa-type') and opaque-id and opaque-type) or (not(derived-from(type, 'ospfv2-opaque-lsa-type')) and not(opaque-id) and not(opaque-type))" {
                                description
                                  "The opaque-type and the opaque-id only apply to
                                   Opaque-LSAs.";
                              }
                              config false;
                              status current;
                              description
                                "Decoded OSPFv2 LSA header data.";
                              container lsa-options {
                                config false;
                                status current;
                                description
                                  "LSA Options.";
                                leaf-list lsa-options {
                                  type identityref {
                                    base ospfv2-lsa-option;
                                  }
                                  config false;
                                  min-elements 0;
                                  max-elements 4294967295;
                                  ordered-by user;
                                  status current;
                                  description
                                    "List of LSA Options.  This list will contain the
                                     identities for the OSPFv2 LSA Options that are set.";
                                }
                              }
                              leaf lsa-id {
                                type string {
                                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                                }
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "Link State ID.";
                              }
                              leaf opaque-type {
                                type uint8;
                                config false;
                                status current;
                                description
                                  "Opaque-LSA type.";
                              }
                              leaf opaque-id {
                                type uint32 {
                                  range "0..16777215";
                                }
                                config false;
                                status current;
                                description
                                  "Opaque-LSA ID.";
                              }
                              leaf age {
                                type uint16;
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA age.";
                              }
                              leaf type {
                                type identityref {
                                  base ospf-lsa-type;
                                }
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA type.";
                              }
                              leaf adv-router {
                                type string {
                                  pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                                }
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA advertising router.";
                              }
                              leaf seq-num {
                                type uint32;
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA sequence number.";
                              }
                              leaf checksum {
                                type string {
                                  pattern "(0x)?[0-9a-fA-F]{4}";
                                }
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA checksum.";
                              }
                              leaf length {
                                type uint16;
                                config false;
                                mandatory true;
                                status current;
                                description
                                  "LSA length, including the header.";
                              }
                            }
                            container body {
                              config false;
                              status current;
                              description
                                "Decoded OSPFv2 LSA body data.";
                              container router {
                                when "derived-from-or-self(../../header/type, 'ospfv2-router-lsa')" {
                                  description
                                    "Only applies to Router-LSAs.";
                                }
                                config false;
                                status current;
                                description
                                  "Router-LSA.";
                                container router-bits {
                                  config false;
                                  status current;
                                  description
                                    "Router-LSA bits.";
                                  leaf-list rtr-lsa-bits {
                                    type identityref {
                                      base router-lsa-bit;
                                    }
                                    config false;
                                    min-elements 0;
                                    max-elements 4294967295;
                                    ordered-by user;
                                    status current;
                                    description
                                      "List of Router-LSA bits.  This list will contain
                                       identities for the bits; these identities are set
                                       in the Router-LSA bits.";
                                  }
                                }
                                leaf num-of-links {
                                  type uint16;
                                  config false;
                                  status current;
                                  description
                                    "Number of links in the Router-LSA.";
                                }
                                container links {
                                  config false;
                                  status current;
                                  description
                                    "All router links.";
                                  list link {
                                    config false;
                                    min-elements 0;
                                    max-elements 4294967295;
                                    ordered-by user;
                                    status current;
                                    description
                                      "Router-LSA link.";
                                    leaf link-id {
                                      type union {
                                        type string {
                                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                        }
                                        type string {
                                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                                        }
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Router-LSA Link ID.";
                                    }
                                    leaf link-data {
                                      type union {
                                        type string {
                                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                        }
                                        type uint32;
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Router-LSA link data.";
                                    }
                                    leaf type {
                                      type enumeration {
                                        enum "point-to-point-link" {
                                          value 1;
                                          status current;
                                          description
                                            "Point-to-point link to another router.";
                                        }
                                        enum "transit-network-link" {
                                          value 2;
                                          status current;
                                          description
                                            "Link to a transit network, identified by the DR.";
                                        }
                                        enum "stub-network-link" {
                                          value 3;
                                          status current;
                                          description
                                            "Link to a stub network, identified by the subnet.";
                                        }
                                        enum "virtual-link" {
                                          value 4;
                                          status current;
                                          description
                                            "Virtual link across a transit area.";
                                        }
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Router-LSA link type.";
                                    }
                                    container topologies {
                                      config false;
                                      status current;
                                      description
                                        "All topologies for the link.";
                                      list topology {
                                        config false;
                                        min-elements 0;
                                        max-elements 4294967295;
                                        ordered-by user;
                                        status current;
                                        description
                                          "Topology-specific information.";
                                        leaf mt-id {
                                          type uint8;
                                          config false;
                                          status current;
                                          description
                                            "The MT-ID for the topology enabled on the link.";
                                        }
                                        leaf metric {
                                          type uint16;
                                          config false;
                                          status current;
                                          description
                                            "Metric for the topology.";
                                        }
                                      }
                                    }
                                  }
                                }
                              }
                              container network {
                                when "derived-from-or-self(../../header/type, 'ospfv2-network-lsa')" {
                                  description
                                    "Only applies to Network-LSAs.";
                                }
                                config false;
                                status current;
                                description
                                  "Network-LSA.";
                                leaf network-mask {
                                  type string {
                                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                                  }
                                  config false;
                                  status current;
                                  description
                                    "The IP address mask for the network.";
                                }
                                container attached-routers {
                                  config false;
                                  status current;
                                  description
                                    "All attached routers.";
                                  leaf-list attached-router {
                                    type string {
                                      pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                    }
                                    config false;
                                    min-elements 0;
                                    max-elements 4294967295;
                                    ordered-by user;
                                    status current;
                                    description
                                      "List of the routers attached to the network.";
                                  }
                                }
                              }
                              container summary {
                                when "derived-from(../../header/type, 'ospfv2-summary-lsa-type')" {
                                  description
                                    "Only applies to summary LSAs.";
                                }
                                config false;
                                status current;
                                description
                                  "Summary LSA.";
                                leaf network-mask {
                                  type string {
                                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                  }
                                  config false;
                                  status current;
                                  description
                                    "The IP address mask for the network.";
                                }
                                container topologies {
                                  config false;
                                  status current;
                                  description
                                    "All topologies for the summary LSA.";
                                  list topology {
                                    config false;
                                    min-elements 0;
                                    max-elements 4294967295;
                                    ordered-by user;
                                    status current;
                                    description
                                      "Topology-specific information.";
                                    leaf mt-id {
                                      type uint8;
                                      config false;
                                      status current;
                                      description
                                        "The MT-ID for the topology enabled for the summary.";
                                    }
                                    leaf metric {
                                      type uint32 {
                                        range "0..16777215";
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Metric for the topology.";
                                    }
                                  }
                                }
                              }
                              container external {
                                when "derived-from(../../header/type, 'ospfv2-external-lsa-type')" {
                                  description
                                    "Only applies to AS-External-LSAs and NSSA-LSAs.";
                                }
                                config false;
                                status current;
                                description
                                  "External-LSA.";
                                leaf network-mask {
                                  type string {
                                    pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                  }
                                  config false;
                                  status current;
                                  description
                                    "The IP address mask for the network.";
                                }
                                container topologies {
                                  config false;
                                  status current;
                                  description
                                    "All topologies for the External-LSA.";
                                  list topology {
                                    config false;
                                    min-elements 0;
                                    max-elements 4294967295;
                                    ordered-by user;
                                    status current;
                                    description
                                      "Topology-specific information.";
                                    leaf mt-id {
                                      type uint8;
                                      config false;
                                      status current;
                                      description
                                        "The MT-ID for the topology enabled for the
                                         external or NSSA prefix.";
                                    }
                                    leaf flags {
                                      type bits {
                                        bit "E" {
                                          position 0;
                                          status current;
                                          description
                                            "When set, the metric specified is a Type 2
                                             external metric.";
                                        }
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Topology flags.";
                                    }
                                    leaf metric {
                                      type uint32 {
                                        range "0..16777215";
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Metric for the topology.";
                                    }
                                    leaf forwarding-address {
                                      type string {
                                        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                      }
                                      config false;
                                      status current;
                                      description
                                        "IPv4 Forwarding address.";
                                    }
                                    leaf external-route-tag {
                                      type uint32;
                                      config false;
                                      status current;
                                      description
                                        "Route tag for the topology.";
                                    }
                                  }
                                }
                              }
                              container opaque {
                                when "derived-from(../../header/type, 'ospfv2-opaque-lsa-type')" {
                                  description
                                    "Only applies to Opaque-LSAs.";
                                }
                                config false;
                                status current;
                                description
                                  "Opaque-LSA.";
                                container ri-opaque {
                                  config false;
                                  status current;
                                  description
                                    "OSPF Router-Information-Opaque-LSA.";
                                  reference
                                    "RFC 7770: Extensions to OSPF for Advertising Optional
                                     Router Capabilities";
                                  container router-capabilities-tlv {
                                    config false;
                                    status current;
                                    description
                                      "Informational and functional router capabilities.";
                                    container router-informational-capabilities {
                                      config false;
                                      status current;
                                      description
                                        "OSPF Router Informational Flag definitions.";
                                      leaf-list informational-capabilities {
                                        type identityref {
                                          base informational-capability;
                                        }
                                        config false;
                                        min-elements 0;
                                        max-elements 4294967295;
                                        ordered-by user;
                                        status current;
                                        description
                                          "List of informational capabilities.  This list will
                                           contain the identities for the informational
                                           capabilities supported by the router.";
                                      }
                                    }
                                    list informational-capabilities-flags {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "List of informational capability flags.  This will
                                         return all the 32-bit informational flags, irrespective
                                         of whether or not they are known to the device.";
                                      leaf informational-flag {
                                        type uint32;
                                        config false;
                                        status current;
                                        description
                                          "Individual informational capability flag.";
                                      }
                                    }
                                    list functional-capabilities {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "List of functional capability flags.  This will
                                         return all the 32-bit functional flags, irrespective
                                         of whether or not they are known to the device.";
                                      leaf functional-flag {
                                        type uint32;
                                        config false;
                                        status current;
                                        description
                                          "Individual functional capability flag.";
                                      }
                                    }
                                  }
                                  container node-tag-tlvs {
                                    config false;
                                    status current;
                                    description
                                      "All Node Admin Tag TLVs.";
                                    list node-tag-tlv {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "Node Admin Tag TLV.";
                                      list node-tag {
                                        config false;
                                        min-elements 0;
                                        max-elements 4294967295;
                                        ordered-by user;
                                        status current;
                                        description
                                          "List of tags.";
                                        leaf tag {
                                          type uint32;
                                          config false;
                                          status current;
                                          description
                                            "Value of the node administrative tag.";
                                        }
                                      }
                                    }
                                  }
                                  container dynamic-hostname-tlv {
                                    config false;
                                    status current;
                                    description
                                      "OSPF Dynamic Hostname TLV.";
                                    leaf hostname {
                                      type string {
                                        length "1..255";
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Dynamic hostname.";
                                    }
                                  }
                                  container sbfd-discriminator-tlv {
                                    config false;
                                    status current;
                                    description
                                      "OSPF S-BFD Discriminator TLV.";
                                    list sbfd-discriminators {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "List of S-BFD Discriminators.";
                                      leaf sbfd-discriminator {
                                        type uint32;
                                        config false;
                                        status current;
                                        description
                                          "Individual S-BFD Discriminator.";
                                      }
                                    }
                                  }
                                  container maximum-sid-depth-tlv {
                                    config false;
                                    status current;
                                    description
                                      "OSPF Node MSD TLV.";
                                    list msd-type {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "List of MSD tuples.";
                                      leaf msd-type {
                                        type uint8;
                                        config false;
                                        status current;
                                        description
                                          "Maximum SID Depth (MSD) type.";
                                      }
                                      leaf msd-value {
                                        type uint8;
                                        config false;
                                        status current;
                                        description
                                          "MSD value for the type.";
                                      }
                                    }
                                  }
                                  container unknown-tlvs {
                                    config false;
                                    status current;
                                    description
                                      "All unknown TLVs.";
                                    list unknown-tlv {
                                      config false;
                                      min-elements 0;
                                      max-elements 4294967295;
                                      ordered-by user;
                                      status current;
                                      description
                                        "Unknown TLV.";
                                      leaf type {
                                        type uint16;
                                        config false;
                                        status current;
                                        description
                                          "TLV type.";
                                      }
                                      leaf length {
                                        type uint16;
                                        config false;
                                        status current;
                                        description
                                          "TLV length (octets).";
                                      }
                                      leaf value {
                                        type string {
                                          pattern "([0-9a-fA-F]{2}(:[0-9a-fA-F]{2})*)?";
                                        }
                                        config false;
                                        status current;
                                        description
                                          "TLV value.";
                                      }
                                    }
                                  }
                                }
                                container te-opaque {
                                  config false;
                                  status current;
                                  description
                                    "OSPFv2 TE Opaque-LSA.";
                                  reference
                                    "RFC 3630: Traffic Engineering (TE) Extensions to
                                     OSPF Version 2";
                                  container router-address-tlv {
                                    config false;
                                    status current;
                                    description
                                      "Router address TLV.";
                                    leaf router-address {
                                      type string {
                                        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                      }
                                      config false;
                                      status current;
                                      description
                                        "Router address.";
                                    }
                                  }
                                  container link-tlv {
                                    config false;
                                    status current;
                                    description
                                      "Describes a single link.  It is constructed
                                       from a set of sub-TLVs.";
                                    leaf link-type {
                                      type enumeration {
                                        enum "point-to-point-link" {
                                          value 1;
                                          status current;
                                          description
                                            "Point-to-point link to another router.";
                                        }
                                        enum "transit-network-link" {
                                          value 2;
                                          status current;
                                          description
                                            "Link to a transit network, identified by the DR.";
                                        }
                                        enum "stub-network-link" {
                                          value 3;
                                          status current;
                                          description
                                            "Link to a stub network, identified by the subnet.";
                                        }
                                        enum "virtual-link" {
                                          value 4;
                                          status current;
                                          description
                                            "Virtual link across a transit area.";
                                        }
                                      }
                                      config false;
                                      mandatory true;
                                      status current;
                                      description
                                        "Link type.";
                                    }
                                    leaf link-id {
                                      type union {
                                        type string {
                                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                                        }
                                        type string {
                                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                                        }
                                      }
                                      config false;
                                      mandatory true;
                                      status current;
                                      description
                                        "Link ID.";
                                    }
                                    container local-if-ipv4-addrs {
                                      config false;
                                      status current;
                                      description
                                        "All local interface IPv4 addresses.";
