                  }
                  leaf interface-type {
                    type enumeration {
                      enum "broadcast" {
                        value 0;
                        status current;
                        description
                          "Specifies an OSPF broadcast multi-access network.";
                      }
                      enum "non-broadcast" {
                        value 1;
                        status current;
                        description
                          "Specifies an OSPF Non-Broadcast Multi-Access
                           (NBMA) network.";
                      }
                      enum "point-to-multipoint" {
                        value 2;
                        status current;
                        description
                          "Specifies an OSPF point-to-multipoint network.";
                      }
                      enum "point-to-point" {
                        value 3;
                        status current;
                        description
                          "Specifies an OSPF point-to-point network.";
                      }
                      enum "hybrid" {
                        value 4;
                        status current;
                        description
                          "Specifies an OSPF hybrid broadcast /
                           point-to-multipoint network.";
                      }
                    }
                    config true;
                    status current;
                    description
                      "Interface type.";
                  }
                  leaf passive {
                    type boolean;
                    config true;
                    status current;
                    description
                      "Enables/disables a passive interface.  A passive
                       interface's prefix will be advertised, but no neighbor
                       adjacencies will be formed on the interface.";
                  }
                  leaf demand-circuit {
                    type boolean;
                    config true;
                    status current;
                    description
                      "Enables/disables a demand circuit.";
                  }
                  leaf priority {
                    type uint8;
                    config true;
                    status current;
                    description
                      "Configures OSPF router priority.  In a multi-access
                       network, this value is for Designated Router (DR) election.
                       The priority is ignored on other interface types.  A router
                       with a higher priority will be preferred in the election.
                       A value of 0 indicates that the router is not eligible to
                       become the DR or Backup DR (BDR).";
                  }
                  container multi-areas {
                    config true;
                    status current;
                    description
                      "Container for multi-area configuration.";
                    list multi-area {
                      key "multi-area-id";
                      config true;
                      min-elements 0;
                      max-elements 4294967295;
                      ordered-by system;
                      status current;
                      description
                        "Configures an OSPF multi-area adjacency.";
                      leaf multi-area-id {
                        type string {
                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                        }
                        config true;
                        status current;
                        description
                          "Multi-area adjacency area ID.";
                      }
                      leaf cost {
                        type uint16 {
                          range "0..65535";
                        }
                        config true;
                        status current;
                        description
                          "Interface cost for a multi-area adjacency.";
                      }
                    }
                  }
                  container static-neighbors {
                    config true;
                    status current;
                    description
                      "Statically configured neighbors.";
                    list neighbor {
                      key "identifier";
                      config true;
                      min-elements 0;
                      max-elements 4294967295;
                      ordered-by system;
                      status current;
                      description
                        "Specifies a static OSPF neighbor.";
                      leaf identifier {
                        type union {
                          type string {
                            pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                          }
                          type string {
                            pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                            pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                          }
                        }
                        config true;
                        status current;
                        description
                          "Neighbor's Router ID, IPv4 address, or IPv6 address.";
                      }
                      leaf cost {
                        type uint16 {
                          range "0..65535";
                        }
                        config true;
                        status current;
                        description
                          "Interface cost.  Different implementations have
                           different default costs, with some defaulting to a
                           cost inversely proportional to the interface speed.
                           Others will default to 1, equating the cost to a
                           hop count.";
                      }
                      leaf poll-interval {
                        type uint16;
                        units "seconds";
                        config true;
                        status current;
                        description
                          "Neighbor's poll interval (seconds) for sending OSPF
                           Hello packets to discover the neighbor on NBMA
                           networks.  This interval dictates the granularity for
                           discovery of new neighbors.  A sample would be
                           120 seconds (2 minutes) for a legacy Packet Data
                           Network (PDN) X.25 network.";
                        reference
                          "RFC 2328: OSPF Version 2, Appendix C.5";
                      }
                      leaf priority {
                        type uint8;
                        config true;
                        status current;
                        description
                          "Neighbor's priority for DR election.  A router with a
                           higher priority will be preferred in the election.
                           A value of 0 indicates that the router is not
                           eligible to become the DR or BDR.";
                      }
                    }
                  }
                  leaf node-flag {
                    type boolean;
                    default "false";
                    config true;
                    status current;
                    description
                      "Sets the prefix as identifying the advertising router.";
                    reference
                      "RFC 7684: OSPFv2 Prefix/Link Attribute Advertisement";
                  }
                  container bfd {
                    config true;
                    status current;
                    description
                      "BFD interface configuration.";
                    reference
                      "RFC 5880: Bidirectional Forwarding Detection (BFD)
                       RFC 5881: Bidirectional Forwarding Detection
                       (BFD) for IPv4 and IPv6 (Single Hop)
                       RFC 9314: YANG Data Model for Bidirectional Forwarding
                       Detection (BFD)";
                    leaf enabled {
                      type boolean;
                      default "false";
                      config true;
                      status current;
                      description
                        "Indicates whether BFD is enabled.";
                    }
                  }
                  container fast-reroute {
                    config true;
                    status current;
                    description
                      "Interface IP-FRR configuration.";
                    container lfa {
                      config true;
                      status current;
                      description
                        "LFA configuration.";
                      leaf candidate-enabled {
                        type boolean;
                        default "true";
                        config true;
                        status current;
                        description
                          "Enables the interface to be used as a backup.";
                      }
                      leaf enabled {
                        type boolean;
                        default "false";
                        config true;
                        status current;
                        description
                          "Activates an LFA.  Per-prefix LFA computation
                           is assumed.";
                      }
                      container remote-lfa {
                        config true;
                        status current;
                        description
                          "R-LFA configuration.";
                        leaf enabled {
                          type boolean;
                          default "false";
                          config true;
                          status current;
                          description
                            "Activates a Remote LFA (R-LFA).";
                        }
                      }
                    }
                  }
                  leaf hello-interval {
                    type uint16;
                    units "seconds";
                    config true;
                    status current;
                    description
                      "Interval between Hello packets (seconds).  It must
                       be the same for all routers on the same network.
                       Different networks, implementations, and deployments
                       will use different Hello intervals.  A sample value
                       for a LAN network would be 10 seconds.";
                    reference
                      "RFC 2328: OSPF Version 2, Appendix C.3";
                  }
                  leaf dead-interval {
                    type uint16;
                    units "seconds";
                    must "../dead-interval > ../hello-interval" {
                      error-message
                        "The dead interval must be larger than the Hello interval";
                      description
                        "The value must be greater than 'hello-interval'.";
                    }
                    config true;
                    status current;
                    description
                      "Interval after which a neighbor is declared down
                       (seconds) if Hello packets are not received.  It is
                       typically 3 or 4 times the 'hello-interval' period.
                       A typical value for LAN networks is 40 seconds.";
                    reference
                      "RFC 2328: OSPF Version 2, Appendix C.3";
                  }
                  leaf retransmit-interval {
                    type uint16 {
                      range "1..3600";
                    }
                    units "seconds";
                    config true;
                    status current;
                    description
                      "Interval between retransmitting unacknowledged Link
                       State Advertisements (LSAs) (seconds).  This should
                       be well over the round-trip transmit delay for
                       any two routers on the network.  A sample value
                       would be 5 seconds.";
                    reference
                      "RFC 2328: OSPF Version 2, Appendix C.3";
                  }
                  leaf transmit-delay {
                    type uint16;
                    units "seconds";
                    config true;
                    status current;
                    description
                      "Estimated time needed to transmit Link State Update
                       (LSU) packets on the interface (seconds).  LSAs have
                       their age incremented by this amount when advertised
                       on the interface.  A sample value would be 1 second.";
                    reference
                      "RFC 2328: OSPF Version 2, Appendix C.3";
                  }
                  leaf lls {
                    type boolean;
                    config true;
                    status current;
                    description
                      "Enables/disables link-local signaling (LLS) support.";
                  }
                  container ttl-security {
                    config true;
                    status current;
                    description
                      "Time to Live (TTL) security checking.";
                    leaf enabled {
                      type boolean;
                      config true;
                      status current;
                      description
                        "Enables/disables TTL security checking.";
                    }
                    leaf hops {
                      type uint8 {
                        range "1..254";
                      }
                      default "1";
                      config true;
                      status current;
                      description
                        "Maximum number of hops that an OSPF packet may
                         have traversed before reception.";
                    }
                  }
                  leaf enabled {
                    type boolean;
                    default "true";
                    config true;
                    status current;
                    description
                      "Enables/disables the OSPF protocol on the interface.";
                  }
                  container authentication {
                    config true;
                    status current;
                    description
                      "Authentication configuration.";
                    choice auth-type-selection {
                      config true;
                      status current;
                      description
                        "Options for OSPFv2/OSPFv3 authentication
                         configuration.";
                      case ospfv2-auth {
                        when "derived-from-or-self(../../../../../../rt:type, 'ospfv2')" {
                          description
                            "Applied to OSPFv2 only.";
                        }
                        config true;
                        status current;
                        leaf ospfv2-auth-trailer-rfc {
                          type enumeration {
                            enum "rfc5709" {
                              value 0;
                              status current;
                              description
                                "Support for the OSPF authentication trailer as
                                 described in RFC 5709.";
                              reference
                                "RFC 5709: OSPFv2 HMAC-SHA Cryptographic Authentication";
                            }
                            enum "rfc7474" {
                              value 1;
                              status current;
                              description
                                "Support for the OSPF authentication trailer as
                                 described in RFC 7474.";
                              reference
                                "RFC 7474: Security Extension for OSPFv2
                                 When Using Manual Key Management";
                            }
                          }
                          config true;
                          status current;
                          description
                            "Version of OSPFv2 authentication trailer support.
                             See RFCs 5709 and 7474.";
                          reference
                            "RFC 5709: OSPFv2 HMAC-SHA Cryptographic Authentication
                             RFC 7474: Security Extension for OSPFv2 When Using
                             Manual Key Management";
                        }
                        choice ospfv2-auth-specification {
                          config true;
                          status current;
                          description
                            "Key chain or explicit key parameter specification.";
                          case auth-key-chain {
                            config true;
                            status current;
                            leaf ospfv2-key-chain {
                              type leafref {
                                path "/key-chain:key-chains/key-chain:key-chain/key-chain:name";
                                require-instance true;
                                type string;
                              }
                              config true;
                              status current;
                              description
                                "Name of the key chain.";
                            }
                          }
                          case auth-key-explicit {
                            config true;
                            status current;
                            leaf ospfv2-key-id {
                              type uint32;
                              config true;
                              status current;
                              description
                                "Key identifier.";
                            }
                            leaf ospfv2-key {
                              type string;
                              config true;
                              status current;
                              description
                                "OSPFv2 authentication key.  The
                                 length of the key may be dependent on the
                                 cryptographic algorithm.";
                            }
                            leaf ospfv2-crypto-algorithm {
                              type identityref {
                                base crypto-algorithm;
                              }
                              config true;
                              status current;
                              description
                                "Cryptographic algorithm associated with the key.";
                            }
                          }
                        }
                      }
                      case ospfv3-auth-ipsec {
                        when "derived-from-or-self(../../../../../../rt:type, 'ospfv3')" {
                          description
                            "Applied to OSPFv3 only.";
                        }
                        config true;
                        status current;
                        leaf sa {
                          type string;
                          config true;
                          status current;
                          description
                            "Name of the Security Association (SA).";
                        }
                      }
                      case ospfv3-auth-trailer {
                        when "derived-from-or-self(../../../../../../rt:type, 'ospfv3')" {
                          description
                            "Applied to OSPFv3 only.";
                        }
                        config true;
                        status current;
                        choice ospfv3-auth-specification {
                          config true;
                          status current;
                          description
                            "Key chain or explicit key parameter specification.";
                          case auth-key-chain {
                            config true;
                            status current;
                            leaf ospfv3-key-chain {
                              type leafref {
                                path "/key-chain:key-chains/key-chain:key-chain/key-chain:name";
                                require-instance true;
                                type string;
                              }
                              config true;
                              status current;
                              description
                                "Name of the key chain.";
                            }
                          }
                          case auth-key-explicit {
                            config true;
                            status current;
                            leaf ospfv3-sa-id {
                              type uint16;
                              config true;
                              status current;
                              description
                                "Security Association (SA) Identifier.";
                            }
                            leaf ospfv3-key {
                              type string;
                              config true;
                              status current;
                              description
                                "OSPFv3 authentication key.  The
                                 length of the key may be dependent on the
                                 cryptographic algorithm.";
                            }
                            leaf ospfv3-crypto-algorithm {
                              type identityref {
                                base crypto-algorithm;
                              }
                              config true;
                              status current;
                              description
                                "Cryptographic algorithm associated with the key.";
                            }
                          }
                        }
                      }
                    }
                  }
                  leaf cost {
                    type uint16 {
                      range "0..65535";
                    }
                    config true;
                    status current;
                    description
                      "Interface's cost.";
                  }
                  leaf mtu-ignore {
                    type boolean;
                    config true;
                    status current;
                    description
                      "Enables/disables bypassing the MTU mismatch check in
                       Database Description packets as specified in Section 10.6
                       of RFC 2328.";
                    reference
                      "RFC 2328: OSPF Version 2, Section 10.6";
                  }
                  leaf prefix-suppression {
                    type boolean;
                    config true;
                    status current;
                    description
                      "Suppresses advertisement of the prefixes associated
                       with the interface.";
                  }
                  leaf state {
                    type enumeration {
                      enum "down" {
                        value 1;
                        status current;
                        description
                          "Interface is in the 'Down' state.";
                      }
                      enum "loopback" {
                        value 2;
                        status current;
                        description
                          "Interface is in the 'Loopback' state.";
                      }
                      enum "waiting" {
                        value 3;
                        status current;
                        description
                          "Interface is in the 'Waiting' state.";
                      }
                      enum "point-to-point" {
                        value 4;
                        status current;
                        description
                          "Interface is in the 'Point-to-point' state.";
                      }
                      enum "dr" {
                        value 5;
                        status current;
                        description
                          "Interface is in the 'DR' (Designated Router) state.";
                      }
                      enum "bdr" {
                        value 6;
                        status current;
                        description
                          "Interface is in the 'Backup' (Backup Designated Router
                           (BDR)) state.";
                      }
                      enum "dr-other" {
                        value 7;
                        status current;
                        description
                          "Interface is in the 'DR Other' state.";
                      }
                    }
                    config false;
                    status current;
                    description
                      "Interface state.";
                  }
                  leaf hello-timer {
                    type union {
                      type uint16 {
                        range "1..65535";
                      }
                      type enumeration {
                        enum "infinity" {
                          value 0;
                          status current;
                          description
                            "The timer is set to infinity.";
                        }
                        enum "not-set" {
                          value 1;
                          status current;
                          description
                            "The timer is not set.";
                        }
                      }
                    }
                    units "seconds";
                    config false;
                    status current;
                    description
                      "This timer tracks the remaining time before the
                       next Hello packet is sent on the interface.";
                  }
                  leaf wait-timer {
                    type union {
                      type uint16 {
                        range "1..65535";
                      }
                      type enumeration {
                        enum "infinity" {
                          value 0;
                          status current;
                          description
                            "The timer is set to infinity.";
                        }
                        enum "not-set" {
                          value 1;
                          status current;
                          description
                            "The timer is not set.";
                        }
                      }
                    }
                    units "seconds";
                    config false;
                    status current;
                    description
                      "This timer tracks the remaining time before
                       the interface exits the 'Waiting' state.";
                  }
                  leaf dr-router-id {
                    type string {
                      pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                    }
                    config false;
                    status current;
                    description
                      "DR Router ID.";
                  }
                  leaf dr-ip-addr {
                    type union {
                      type string {
                        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                      }
                      type string {
                        pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                        pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                      }
                    }
                    config false;
                    status current;
                    description
                      "DR IP address.";
                  }
                  leaf bdr-router-id {
                    type string {
                      pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                    }
                    config false;
                    status current;
                    description
                      "BDR Router ID.";
                  }
                  leaf bdr-ip-addr {
                    type union {
                      type string {
                        pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                      }
                      type string {
                        pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                        pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
                      }
                    }
                    config false;
                    status current;
                    description
                      "BDR IP address.";
                  }
                  container statistics {
                    config false;
                    status current;
                    description
                      "Per-interface statistics.";
                    leaf discontinuity-time {
                      type string {
                        pattern "[0-9]{4}-(1[0-2]|0[1-9])-(0[1-9]|[1-2][0-9]|3[0-1])T(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[\\+\\-]((1[0-3]|0[0-9]):([0-5][0-9])|14:00))?";
                      }
                      config false;
                      status current;
                      description
                        "The time of the most recent occasion at which any one or
                         more of this OSPF interface's counters suffered a
                         discontinuity.  If no such discontinuities have occurred
                         since the OSPF interface was last reinitialized, then
                         this node contains the time the OSPF interface was
                         reinitialized, which normally occurs when it was
                         created.";
                    }
                    leaf if-event-count {
                      type uint32;
                      config false;
                      status current;
                      description
                        "The number of times this interface has changed its
                         state or an error has occurred.  Discontinuities in the
                         value of this counter can occur when the OSPF interface
                         is reinitialized.";
                    }
                    leaf link-scope-lsa-count {
                      type uint32;
                      config false;
                      status current;
                      description
                        "The number of link-scope LSAs.";
                    }
                    leaf link-scope-lsa-cksum-sum {
                      type uint32;
                      config false;
                      status current;
                      description
                        "The modulo 2^32 sum of the LSA checksums
                         for link-scope LSAs.  The value should be treated as
                         unsigned when comparing two sums of checksums.  While
                         differing checksums indicate a different combination
                         of LSAs, equivalent checksums don't guarantee that the
                         LSAs are the same, given that multiple combinations of
                         LSAs can result in the same checksum.";
                    }
                    container database {
                      config false;
                      status current;
                      description
                        "Container for link-scope LSA type statistics.";
                      list link-scope-lsa-type {
                        config false;
                        min-elements 0;
                        max-elements 4294967295;
                        ordered-by user;
                        status current;
                        description
                          "List of link-scope LSA statistics.";
                        leaf lsa-type {
                          type uint16;
                          config false;
                          status current;
                          description
                            "Link-scope LSA type.";
                        }
                        leaf lsa-count {
                          type uint32;
                          config false;
                          status current;
                          description
                            "The number of LSAs of this LSA type.";
                        }
                        leaf lsa-cksum-sum {
                          type uint32;
                          config false;
                          status current;
                          description
                            "The modulo 2^32 sum of the LSA checksums
                             for LSAs of this type.  The value should be
                             treated as unsigned when comparing two sums of
                             checksums.  While differing checksums indicate a
                             different combination of LSAs, equivalent checksums
                             don't guarantee that the LSAs are the same, given that
                             multiple combinations of LSAs can result in the same
                             checksum.";
                        }
                      }
                    }
                  }
                  container neighbors {
                    config false;
                    status current;
                    description
                      "All neighbors for the interface.";
                    list neighbor {
                      key "neighbor-router-id";
                      config false;
                      min-elements 0;
                      max-elements 4294967295;
                      ordered-by user;
                      status current;
                      description
                        "List of interface OSPF neighbors.";
                      leaf neighbor-router-id {
                        type string {
                          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])";
                        }
                        config false;
                        status current;
                        description
                          "Neighbor's Router ID.";
                      }
                      leaf address {
                        type union {
                          type string {
                            pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
                          }
                          type string {
